function pfHash(s){let h=7;for(const ch of s)h=(h*31+ch.charCodeAt(0))>>>0;return h;}
function pfGen(n,d,era,fem){const h=pfHash(n),p=(a,k)=>a[(h>>>(k||0))%a.length];
  const hc=p(['#2b2420','#2b2420','#3a2b20','#5a4632','#8d877c','#cfc8ba'],3),m=d==='M';
  if(fem){if(era==='jo')return 'c=jeogori,cc='+p(['#e9d9b0','#cfe0d6','#e7c9c4'],2)+',h=jbun';
    if(era==='w19'||era==='w18')return 'c=dress19,cc='+p(['#3a2f3f','#2b3a55','#4b3a26'],2)+',h=bun,hc='+hc;
    return 'c=blouse,cc='+p(['#2b3a55','#7a2e2a','#3a3a3a','#2e5a3a'],2)+',h=bob,hc='+p(['#2b2420','#5a4632','#8d877c'],4);}
  const fh=(a)=>p(a,5);
  switch(era){
   case 'cn':return 'c=hanfu,cc='+p(['#3d5a80','#5d4b3a','#2e5a3a','#7a2e2a','#4a3d7a','#1d1b18'],2)+',hw='+(m?'iron':'gwan')+',f='+fh(['mus+goatee','full','long','mus+jbeard','mus','mus+jbeard'])+',hc='+p(['#2b2420','#2b2420','#8d877c','#cfc8ba'],6);
   case 'kg':return (m?'c=gap,cc=#5d4b3a,hw=iron':'c=hanfu,cc='+p(['#2e5a3a','#7a5a2e','#3d5a80'],2)+',hw=gwan')+',f='+fh(['mus+jbeard','full','mus+goatee']);
   case 'jo':return 'c=dan,cc='+p(['#2f5f7a','#2e6b4a','#8f2a1d','#3d5a80'],2)+',hw=samo,f='+fh(['mus+jbeard','mus+goatee','full','mus','mus+jbeard'])+',hc='+p(['#2b2420','#2b2420','#8d877c'],6);
   case 'jm':return 'c=gap,cc='+p(['#7a2e2a','#2c4a6b'],2)+',hw=jeonrip,f='+fh(['mus+jbeard','full','mus+goatee']);
   case 'mk':return 'c=robe,cc=#8a7a5a,h=none';
   case 'gr':return 'c=toga,cc='+p(['#7a2e2a','#4a3d7a','#8a7a5a','#2e5a3a'],2)+',h='+p(['curly','short','bald'],4)+',hc='+hc+(h%3===0?',f=full':'');
   case 'eu':return 'c=ruff,cc='+p(['#1d1b18','#4b3a26','#2b3a55','#5a2a2a'],2)+',h='+p(['long','short','side'],4)+',hc='+hc+',f='+fh(['mus+goatee','','mus']);
   case 'w18':return (m?'c=milcoat,cc=#1f3a5f':'c=coat18,cc='+p(['#1f3a5f','#4b3a26','#5a2a2a','#2e5a3a'],2))+',h=wigw';
   case 'w19':return (m?'c=milcoat,cc='+p(['#1f3a5f','#22314a'],2):d==='H'&&h%2?'c=doctor,t=#1d1b18':'c=bow,cc='+p(['#1d1b18','#3a3a3a','#4b3a26'],2)+',t=#1d1b18')+',h='+p(['side','bald','messy','short'],4)+',hc='+hc+',f='+fh(['full','burns','bigmus','','mus','chin']);
   case 'mo':return 'c=suit,cc=#3a3a3a,t=#7a2e2a,h=short,hc='+hc+',sk=#b98a62';
   default:return (m?'c=mil,cc='+p(['#5b6146','#6b5e3c'],2):d==='H'&&h%2?'c=doctor,t='+p(['#2f5f99','#7a2e2a'],3):'c=suit,cc='+p(['#2b3a55','#3a3a3a','#4b3a26','#22314a'],2)+',t='+p(['#7a2e2a','#2f5f99','#1d1b18','#2e5a3a'],3))+',h='+p(['side','short','bald','side'],4)+',hc='+hc+(h%4===0?',g':'')+(h%5===0?',f=mus':'');}}
