function cnEnc(){const H=CAR.hid=CAR.hid||{},here=n=>CN_HID[n].camps.indexOf(CP.id)>=0&&H[n]!=='done';
  // 황희: 한 사람을 5년 넘게 곁에 둔 뒤
  if(here('황희')){const s=CAR.cn.findIndex(i=>i!=null&&CN[i].t<4&&(CAR.cnMeta[i]||{}).y>=5);if(s>=0)return {n:'황희',kind:'evolve',s:s};}
  // 제갈량: 이미 찾아가기 시작했다면 그다음 걸음
  if(here('제갈량')&&H['제갈량']>0&&Math.random()<.7)return {n:'제갈량',kind:'visit',step:H['제갈량']};
  const L=Object.keys(CN_HID).filter(n=>here(n)&&!CN_HID[n].evolve&&!(H[n]>0)&&(()=>{try{return CN_HID[n].c();}catch(e){return false;}})()).sort(()=>Math.random()-.5);
  for(const n of L)if(Math.random()<CN_HID[n].p)return CN_HID[n].v?{n:n,kind:'visit',step:0}:{n:n,kind:'join'};
  return null;}
const cnByName=n=>CN.find(c=>c.n===n);
const cnHas=f=>cnHired().some(c=>CN_SP[c.n]&&CN_SP[c.n].f===f);
const cnPow=d=>cnHired().filter(c=>c.d===d).reduce((s,c)=>s+CN_POW[c.t],0);
function cnPool(){const tg=CP.id==='joseon'?'j':CP.id==='usa'?'u':'';return CN.filter(c=>(!tg||c.tg.indexOf(tg)>=0)&&!cnHidden(c.n)&&c.n!==(CAR&&CAR.bgn));}
function cnRisk(c){if(c.r){const m=c.r.match(/^([a-z]+)([+-]\d+):(.*)$/);return m?[{k:m[1],v:+m[2],l:m[3]}]:[];}
  const D=CN_DOM[c.d],m=c.d==='S'?c.t-1:c.t-2;if(m<=0)return [];
  const L=[{k:D.rk[0],v:D.rk[1]*m,l:D.rk[2]}];if(D.rk2&&c.t>=3)L.push({k:D.rk2[0],v:D.rk2[1]*(c.t-2),l:D.rk[2]});return L;}
const cnRiskTxt=c=>cnRisk(c).map(x=>CN_KN[x.k]+' '+(x.v>0?'+':'−')+Math.abs(x.v)).join(' · ')+(cnRisk(c).length?' ('+cnRisk(c)[0].l+')':'');
// 잔류 기준. 전설은 1년 뒤 연임 심사(자기 분야 70 이상 · 혼란 30 이하 · 권력 65 이상)를 받고, 2년이 지나면 반드시 떠난다.
function cnKeep(c){if(c.t<3)return null;const D=CN_DOM[c.d],th=c.t===4?(c.d==='S'?65:D.kd>0?70:30):D.keep[0],v=Math.round(vVal(D.v));return {ok:D.kd>0?v>=th:v<=th,txt:vName(D.v)+' '+th+(D.kd>0?' 이상':' 이하'),v:v};}
function cnEffTxt(c){const D=CN_DOM[c.d],T=CN_POW[c.t],nm=c.d==='U'||c.d==='C'?'혼란':vName(D.v);
  return D.eff+' '+nm+' '+(c.d==='U'||c.d==='C'?'−':'+')+T+(c.d==='S'?' · 승부수 성공률 상승':'')+(c.t===1?' (성공했을 때만)':'');}
function cnRoll(mt){const r=Math.random();return Math.max(1,r<.3?mt:r<.65?mt-1:r<.85?mt-2:1);}
function cnLvl(d){return Math.round(vVal(CN_DOM[d].v));}
function cnMaxT(d){const L=cnLvl(d);return L>=60?3:L>=40?2:1;}
function cnPick(pool,d,tt,taken){for(let dt=0;dt<4;dt++)for(const t of dt?[tt-dt,tt+dt]:[tt]){if(t<1||t>(tt===4?4:3))continue;
    const L=pool.filter(c=>c.d===d&&c.t===t&&!taken.has(c.i));if(L.length){const un=L.filter(c=>!CAR.cnSeen.has(c.i));return pk(un.length?un:L);}}return null;}
function cnDraw(){const hired=new Set(CAR.cn.filter(i=>i!=null)),pool=cnPool().filter(c=>!hired.has(c.i)&&!CAR.cnGone.has(c.i)),taken=new Set(),out=[];
  const ds=['H','E','M','A','U','C','S'].sort(()=>Math.random()-.5);ds.push(pk(ds));
  ds.forEach(d=>{const c=cnPick(pool,d,cnRoll(cnMaxT(d)),taken);if(c){taken.add(c.i);out.push({c:c});}});
  // 구원 투수(약하게): 가장 약한 분야에서 낮은 등급 한 명이 올 때가 있다
  const weak=['H','E','M','A'].sort((a,b)=>cnLvl(a)-cnLvl(b))[0];
  if(Math.random()<.45){const c=cnPick(pool,weak,Math.random()<.3?2:1,taken);if(c){taken.add(c.i);out.push({c:c,rescue:1});}}
  // 전설: 그해 국정 점수가 55 이상일 때만, 해마다 많아야 한 명. 그 분야가 충분히 강해야 찾아온다.
  const sc=score(),pL=sc<55?0:Math.min(.4,(sc-55)/70);
  if(Math.random()<pL){const ok=d=>d==='S'?vVal('P')>=60:d==='U'||d==='C'?vVal('X')>=40:cnLvl(d)>=70;
    const L=pool.filter(c=>c.t===4&&ok(c.d)&&!taken.has(c.i));if(L.length){const c=pk(L);taken.add(c.i);out.push({c:c,legend:1});}}
  out.forEach(x=>CAR.cnSeen.add(x.c.i));return out.sort((a,b)=>b.c.t-a.c.t);}
function cnStart(){CAR.cn=[null,null];CAR.cnMeta={};CAR.hid={};CAR.cnSeen=new Set();CAR.cnGone=new Set();CAR.cnLog=[];
  const pool=cnPool(),taken=new Set(),ds=['A','H','E','U','C','M'].sort(()=>Math.random()-.5);
  for(let s=0;s<2;s++){const c=cnPick(pool,ds[s],2,taken);if(c){taken.add(c.i);CAR.cn[s]=c.i;CAR.cnMeta[c.i]={miss:0};CAR.cnSeen.add(c.i);}}
  CAR.cnLog.push('시작: '+cnHired().map(c=>c.n+'(★'+c.t+' '+CN_DOM[c.d].n+')').join(', '));}
// 선택의 결과에 참모 효과를 더한다
function cnBonus(e,t){const out=[];cnHired().forEach(c=>{const D=CN_DOM[c.d];if(D.gain(e)<1||(c.t===1&&t>1))return;
  const T=CN_POW[c.t];apply(D.bon(T),1);out.push(c.n+' · '+(c.d==='U'||c.d==='C'?'혼란 −':vName(D.v)+' +')+T);});return out;}
// 사건마다 각 참모가 자기 분야에 가장 좋은 선택지를 권한다. 분야와 상관없는 사건이면 가장 안전한 쪽을 권한다.
function cnRec(opts){return (CAR.cn||[]).map((i,s)=>{if(i==null)return null;const c=CN[i],D=CN_DOM[c.d];let bk=-1,bg=0,bp=-1,sk=-1,sp=-1;
  opts.forEach((o,k)=>{if(o[1].X)return;const g=D.gain(o[1]),st=stakeOf(o,opts),P=stakeP(fitOf(o,opts).q,st),p=P[0]+P[1];
    if(g>=1&&(g>bg||(g===bg&&p>bp))){bk=k;bg=g;bp=p;}if(p>sp){sp=p;sk=k;}});
  const fav=bk>=0,k=fav?bk:sk,L=fav?D.say:CN_SAFE;return k<0?null:{s:s,c:c,k:k,fav:fav,line:L[(S.turn+c.i)%L.length]};}).filter(Boolean);}
// 연말: 참모의 대가, 잔류 기준, 군사의 해마다 효과
function cnYear(){const notes=[];
  cnHired().forEach(c=>{cnRisk(c).forEach(x=>{S[x.k]=cl(S[x.k]+x.v);});const rt=cnRiskTxt(c);if(rt)notes.push(['r',c,c.n+' · '+rt]);});
  CAR.cn.forEach((i,s)=>{if(i==null)return;const c=CN[i],kp=cnKeep(c),M=CAR.cnMeta[i]||(CAR.cnMeta[i]={miss:0});M.y=(M.y||0)+1;if(!kp)return;
    if(c.t===4){const out=M.y>=2||!kp.ok;if(out){CAR.cn[s]=null;CAR.cnGone.add(i);CAR.cnLog.push(CAR.term+'기 '+Math.round(S.turn/PY)+'년 '+(M.y>=2?'임기 만료':'연임 심사 탈락')+': '+c.n);
        notes.push(['x',c,M.y>=2?'★ '+c.n+'이(가) 2년의 소임을 마치고 떠났다.':'★ '+c.n+'이(가) 연임 심사를 통과하지 못하고 떠났다. ('+kp.txt+', 지금 '+kp.v+')']);}
      else notes.push(['w',c,'★ '+c.n+'이(가) 연임 심사를 통과했다. 한 해 더 머문다. 내년이 마지막이다.']);return;}
    if(kp.ok){M.miss=0;return;}M.miss++;
    if(M.miss>=2){CAR.cn[s]=null;CAR.cnGone.add(i);CAR.cnLog.push(CAR.term+'기 '+Math.round(S.turn/PY)+'년 사직: '+c.n);notes.push(['x',c,c.n+'이(가) 떠났다. '+kp.txt+' 기준을 2년 연속 채우지 못했다.']);}
    else notes.push(['w',c,c.n+'이(가) 실망하고 있다. 내년에도 '+kp.txt+'을(를) 못 채우면 떠난다. (지금 '+kp.v+')']);});
  cnHired().forEach(c=>{const X=CN_SP[c.n];if(X&&X.yr){const r=X.yr();if(r)notes.push(['s',c,'★ '+c.n+' · '+X.n+': '+r]);}});
  if(CAR.endemic===CAR.term){S.e=cl(S.e+3);S.saf=cl(S.saf+3);S.a=cl(S.a+2);notes.push(['s',null,(CAR.endemicN||'엔데믹')+' 이후의 내실: 경제 +3 · 안전망 +3 · 지지율 +2']);}
  if(S.mil>=70){S.e=cl(S.e-1);S.p=cl(S.p+1);notes.push(['m',null,'군사가 강하다: 국방비로 경제 −1, 군의 발언권으로 권력 +1']);}
  else if(S.mil<30&&cnHas('noMil'))notes.push(['s',null,'★ 이순신 · 학익진: 군사가 약하지만 안보 위기를 막아 냈다.']);
  else if(S.mil<30){S.a=cl(S.a-2);notes.push(['m',null,'군사가 약하다: 안보 불안으로 지지율 −2. 국경이 술렁인다.']);const L=(MILEV[CP.id]||[]).filter(e=>e.crisis);if(L.length)queue.push(pk(L));}
  return notes;}
function cnCard(c,body,extra){const kp=cnKeep(c),rk=cnRiskTxt(c),M=(CAR.cnMeta||{})[c.i];
  return '<div class="cn tier'+c.t+(extra||'')+'">'+portrait(c.n,52)+'<div class="cn-x"><div class="cn-h"><b>'+c.n+'</b><span class="cn-t t'+c.t+'">'+'★'.repeat(c.t)+' '+CN_TIER[c.t]+'</span><span class="cn-d">'+CN_DOM[c.d].n+'</span></div>'+
   '<div class="cn-s">'+c.ds+'</div>'+(c.q?'<div class="cn-q">"'+c.q+'" <span class="cn-src">어록 · '+c.qs+'</span></div>':'<div class="cn-q cn-q2">"'+CN_DOM[c.d].say[c.i%3]+'"</div>')+
   (CN_SP[c.n]?'<div class="cn-sp"><b>특수능력 · '+CN_SP[c.n].n+'</b> '+CN_SP[c.n].d+'</div>':'')+
   '<div class="cn-e"><span class="cn-ep">'+cnEffTxt(c)+'</span>'+(rk?'<span class="cn-er">대가: 해마다 '+rk+'</span>':'')+(kp?'<span class="cn-ek'+(kp.ok?'':' bad')+'">'+(c.t===4?'임기 최대 2년 · 1년 뒤 연임 심사: ':'잔류 기준: ')+kp.txt+' (지금 '+kp.v+')'+(c.t===4&&M&&M.y>=1?' · 마지막 해':'')+'</span>':'')+'</div>'+(body||'')+'</div></div>';}
// 비상소집: 커리어에 단 한 번, 전설 등급 후보 셋 가운데 한 명을 곧바로 앉힌다
function cnEmerg(back){window.scrollTo(0,0);const RL=roleOf(),hired=new Set(CAR.cn.filter(i=>i!=null)),L=cnPool().filter(c=>c.t===4&&!hired.has(c.i)&&!CAR.cnGone.has(c.i)).sort(()=>Math.random()-.5),out=[],ds=new Set();
  L.forEach(c=>{if(out.length<3&&!ds.has(c.d)){out.push(c);ds.add(c.d);}});L.forEach(c=>{if(out.length<3&&out.indexOf(c)<0)out.push(c);});
  out.forEach(c=>CAR.cnSeen.add(c.i));SFX.report();vib([40,30,40]);
  R.innerHTML='<div class="gcn deal"><div class="cn-em"><div class="cn-em-k">커리어에 단 한 번</div><div class="hd" style="font-size:28px;color:#fff">비상소집</div>'+
   '<div style="font-size:13.5px;line-height:1.6;color:#e8e2d4;margin-top:4px">전설로 불리는 '+RL.n+' 셋이 부름에 답했다. 한 사람을 지금 바로 앉힐 수 있다. 다만 전설은 기대도 크다. 자기 분야를 2년 연속 지키지 못하면 떠난다.</div></div>'+
   '<div class="cn-l">'+(out.length?out.map((c,j)=>cnCard(c,'<div class="cn-b">'+[0,1].map(s=>'<button class="cn-btn pick" data-em="'+j+','+s+'">'+(CAR.cn[s]==null?'빈 자리에 임명':'<span>'+CN[CAR.cn[s]].n+'</span> 대신')+'</button>').join('')+'</div>')).join(''):'<div class="cn-s">부를 수 있는 전설이 남아 있지 않다.</div>')+'</div>'+
   '<button id="emNo" style="width:100%;padding:13px;font-size:14px">부르지 않고 돌아가기 (기회는 남는다)</button></div>';
  R.querySelectorAll('[data-em]').forEach(b=>b.onclick=()=>{SFX.coin();const [j,s]=b.dataset.em.split(',').map(Number),c=out[j],old=CAR.cn[s],y=Math.floor(S.turn/PY)+1;
    if(old!=null){const o=CN[old];if(o.t>=3)S.a=cl(S.a-1);CAR.cnGone.add(o.i);}
    CAR.cn[s]=c.i;CAR.cnMeta[c.i]={miss:0};CAR.cnEm=CAR.term+'기 '+y+'년 '+c.n;CAR.cnLog.push(CAR.term+'기 '+y+'년 비상소집: '+c.n+'(★4 '+CN_DOM[c.d].n+')'+(old!=null?' ← '+CN[old].n:''));back();});
  document.getElementById('emNo').onclick=()=>{SFX.back();back();};}
const cnEmBtn=()=>CAR&&!CAR.cnEm?'<button id="cnEm" class="cn-embtn">비상소집 · 전설 '+roleOf().n+' 부르기 <small>커리어에 한 번</small></button>':'';
function council(go){window.scrollTo(0,0);const RL=roleOf(),notes=cnYear();let cands=cnDraw(),arm=-1,enc=cnEnc(),dealt=false;const y=Math.round(S.turn/PY)+1;
  const encHTML=()=>{if(!enc)return '';const X=CN_HID[enc.n],c=cnByName(enc.n);
    const sl=act=>'<div class="cn-b">'+[0,1].map(s=>'<button class="cn-btn pick" data-enc="'+act+','+s+'">'+(CAR.cn[s]==null?'빈 자리에 맞이한다':'<span>'+CN[CAR.cn[s]].n+'</span> 대신')+'</button>').join('')+'</div>';
    if(enc.kind==='done')return '<div class="cn-enc"><div class="cn-enc-k">만남</div>'+cnCard(c,'')+'<div class="cn-enc-t" style="margin-top:10px">'+enc.msg+'</div></div>';
    if(enc.kind==='note')return '<div class="cn-enc"><div class="cn-enc-k">찾아감</div><div class="cn-enc-t">'+enc.msg+'</div></div>';
    if(enc.kind==='evolve'){const o=CN[CAR.cn[enc.s]];return '<div class="cn-enc"><div class="cn-enc-k">오랜 세월</div><div class="hd cn-enc-h">'+o.n+'이(가) 물러나며 한 사람을 천거한다</div>'+
      '<div class="cn-enc-t">"다섯 해를 곁에서 모셨습니다. 이제 이 자리에는 더 큰 그릇이 앉아야 합니다." 오래도록 정승 자리를 지킬 사람이라고 한다.</div>'+
      '<div class="cn-enc-w"><span class="cn-q-mark">?</span>'+X.who+'</div>'+
      '<div class="cn-b"><button class="cn-btn pick" data-enc="evolve">'+o.n+' 대신 맞이한다</button><button class="cn-btn" data-enc="skip">'+o.n+'을(를) 그대로 둔다</button></div></div>';}
    const st=enc.kind==='visit'?enc.step:0,last=enc.kind!=='visit'||st>=X.v-1;
    return '<div class="cn-enc"><div class="cn-enc-k">'+(enc.kind==='visit'?'찾아감 '+(st+1)+' / '+X.v:'뜻밖의 만남')+'</div><div class="hd cn-enc-h">'+X.t[0]+'</div><div class="cn-enc-t">'+(X.t[enc.kind==='visit'?st+1:1]||X.t[1])+'</div>'+
      '<div class="cn-enc-w"><span class="cn-q-mark">?</span>'+X.who+'</div>'+
      (enc.kind==='visit'&&!last?'<div class="cn-b"><button class="cn-btn pick" data-enc="visit">찾아간다 (지지율 −2)</button><button class="cn-btn" data-enc="skip">돌아선다 (처음부터 다시)</button></div>':
       sl(enc.kind==='visit'?'visitjoin':'join')+'<div class="cn-b"><button class="cn-btn" data-enc="skip">부르지 않는다</button></div>')+'</div>';};
  const draw=()=>{const slot=s=>{const i=CAR.cn[s];return i==null?'<div class="cn cn-empty"><div class="cn-x"><b>빈 자리</b><div class="cn-s">아래 후보 중에서 '+RL.n+'을 임명하세요.</div></div></div>':
      cnCard(CN[i],'<div class="cn-b"><button data-fire="'+s+'" class="cn-btn">'+(arm===s?'한 번 더 누르면 해임'+(CN[i].t>=3?' (지지율 −1)':''):'해임')+'</button></div>');};
    // 세로 화면: 지금의 참모는 두 칸으로 나란히, 후보는 옆으로 넘기는 카드, 시작 버튼은 아래 고정(pfit)
    const PO=isP();
    R.innerHTML='<div class="gcn'+(dealt?'':' deal')+(PO?' pfit':'')+'">'+(PO?'<div class="p-sc">':'')+'<div class="gcn-k">'+(CP.id==='joseon'?CAR.term+'번째 치세':CAR.term+'기')+' '+y+'년차를 앞두고</div>'+
     '<div class="hd gcn-h">'+RL.meet+'</div><div class="gcn-s">'+RL.sub+'. 자리는 둘이다.</div>'+tip('council')+
     (notes.length?card(lab('지난 한 해의 '+RL.n+' 소식')+notes.map(n=>'<div class="cn-n cn-n'+n[0]+'">'+n[2]+'</div>').join('')):'')+
     encHTML()+lab('지금의 '+RL.n)+'<div class="cn-l cn-now">'+slot(0)+slot(1)+cnEmBtn()+'</div>'+
     lab('올해 찾아온 후보 · '+cands.length+'명'+(PO&&cands.length>1?' · 옆으로 넘겨 보기':''))+'<div class="cn-l cn-cand">'+(cands.length?cands.map((x,j)=>cnCard(x.c,'<div class="cn-b">'+[0,1].map(s=>'<button class="cn-btn pick" data-ap="'+j+','+s+'">'+(CAR.cn[s]==null?'빈 자리에 임명':'<span>'+CN[CAR.cn[s]].n+'</span> 대신')+'</button>').join('')+'</div>',x.rescue?' cn-rescue':'')).join(''):'<div class="cn-s">올해는 찾아온 사람이 없다.</div>')+'</div>'+
     (PO?'</div><div class="p-bt">':'')+'<button id="cnGo" class="pri" style="width:100%;padding:15px;font-size:15px;margin-top:6px">'+y+'년차 시작</button></div>'+(PO?'</div>':'');
    bindTips();dealt=true;pMore();
    R.querySelectorAll('[data-fire]').forEach(b=>b.onclick=()=>{const s=+b.dataset.fire;if(arm!==s){SFX.click();arm=s;return draw();}SFX.fire();
      const c=CN[CAR.cn[s]];if(c.t>=3)S.a=cl(S.a-1);CAR.cnGone.add(c.i);CAR.cnLog.push(CAR.term+'기 '+y+'년 해임: '+c.n);CAR.cn[s]=null;arm=-1;draw();});
    R.querySelectorAll('[data-ap]').forEach(b=>b.onclick=()=>{SFX.coin();const [j,s]=b.dataset.ap.split(',').map(Number),x=cands[j],old=CAR.cn[s];
      if(old!=null){const o=CN[old];if(o.t>=3)S.a=cl(S.a-1);CAR.cnGone.add(o.i);}
      CAR.cn[s]=x.c.i;CAR.cnMeta[x.c.i]={miss:0};CAR.cnLog.push(CAR.term+'기 '+y+'년 임명: '+x.c.n+'(★'+x.c.t+' '+CN_DOM[x.c.d].n+')'+(old!=null?' ← '+CN[old].n:''));
      cands.splice(j,1);arm=-1;draw();});
    document.getElementById('cnGo').onclick=()=>{SFX.click();go();};
    const em=document.getElementById('cnEm');if(em)em.onclick=()=>{SFX.click();cnEmerg(draw);};
    R.querySelectorAll('[data-enc]').forEach(b=>b.onclick=()=>{const [act,ss]=b.dataset.enc.split(','),H=CAR.hid,n=enc.n,c=cnByName(n);
      const seat=s=>{const old=CAR.cn[s];if(old!=null)CAR.cnGone.add(old);CAR.cn[s]=c.i;CAR.cnMeta[c.i]={miss:0,y:0};H[n]='done';CAR.cnSeen.add(c.i);
        CAR.cnLog.push(CAR.term+'기 '+y+'년 히든 합류: '+n+(old!=null?' ← '+CN[old].n:''));SFX.join();vib([30,30,60]);};
      if(act==='skip'){SFX.click();if(enc.kind==='visit')H[n]=0;if(enc.kind==='evolve')H[n]='done';enc=null;return draw();}
      if(act==='visit'){SFX.click();S.a=cl(S.a-2);H[n]=(H[n]||0)+1;CAR.cnLog.push(CAR.term+'기 '+y+'년 '+CN_HID[n].who+' 찾아감 '+H[n]+'회');
        enc={n:n,kind:'note',msg:H[n]===1?'초가를 찾았지만 선비는 만나 주지 않았다. 다음에 또 소식이 올지도 모른다.':'두 번째 걸음도 헛걸음이었다. 그래도 문간에 놓인 편지에는 "다시 오시면"이라고 적혀 있었다.'};return draw();}
      if(act==='evolve'){seat(enc.s);enc={n:n,kind:'done',msg:'오랜 동료가 물러나고, '+n+'이(가) 그 자리에 앉았다.'};return draw();}
      seat(+ss);enc={n:n,kind:'done',msg:act==='visitjoin'?'세 번의 걸음 끝에 '+n+'이(가) 마침내 길을 나섰다.':n+'이(가) 부름에 답했다.'};draw();});};
  draw();}

