function skinOf(e,sid){const s=SKIN[e.t]&&SKIN[e.t][sid];if(!s)return e;
  const r=Object.assign({},e,{t:s.t||e.t,d:s.d||e.d,base:e,o:e.o.map((o,j)=>[s.o&&s.o[j]||o[0],o[1],o[2],o[3]])});
  Object.defineProperty(r,'_skin',{value:[e,sid]});return r;}   // 저장할 때 원본과 위기 id로 적는다(svEnc)

