 tkWhiff:()=>sweep(.16,.05,900,2400,0,1.2),                    // 태권도: 발이 바람을 가른다
 tkWind:()=>tone(520,'triangle',.06,.05),                          // 상대가 발을 든다
 tkBlock:()=>{clk(900,.6);tone(180,'sine',.08,.14);},              // 팔로 막아 냈다
