 simRes:(n,t)=>{for(let i=0;i<n;i++)tone(1200,'square',.02,.04,i*.22);SFX.stamp(n*.22+.15);setTimeout(()=>SFX.medal(t),(n*.22+.35)*1000);},
 swing:()=>sweep(.16,.05,900,2600,0,1.1),                      // 백신 슬래시 칼바람
