const BGM_PLAY={kr:['kr_bgm.mp3','kr_bgm2.mp3'],usa:['america_standardbgm.mp3','america_bgm2.mp3'],joseon:['chosun_bgm.mp3','chosun_bgm2.mp3'],zombie:'zombie_bgm.mp3'};
// 인트로·메인 메뉴 곡: 두 곡이 번갈아 나오고, 처음 들어올 때 어느 곡부터 나올지는 그때그때 다르다
