// 턴 카드: 새 사건이 열릴 때 띠가 화면을 가로지른다. 같은 사건을 다시 그릴 때나 다른 연출이 떠 있을 때는 건너뛴다.
let tfLast=null,alLast=null;
function turnFx(){if(reduceFx()||document.documentElement.dataset.lite||tfLast===cur||document.querySelector('.qfx,.yrfx,.cine'))return false;tfLast=cur;
  const o=document.createElement('div');o.className='turnfx';o.setAttribute('aria-hidden','true');
  o.innerHTML='<div class="turnfx-b"><div class="turnfx-in"><span class="turnfx-k">'+(Math.floor(S.turn/PY)+1)+'년차 · 결정 '+(S.turn%PY+1)+' / '+PY+'</span><span class="turnfx-t">'+cur.t+'</span></div></div>';
  document.body.appendChild(o);if(CP&&CP.dict)skinNode(o);SFX.swoosh();
  const end=()=>{if(o.isConnected)o.remove();};o.onclick=end;setTimeout(end,1250);return true;}
// 게임 화면 단축키: 숫자로 선택지, Enter·Space로 '계속'. 턴 카드가 떠 있으면 먼저 걷는다.
document.addEventListener('keydown',e=>{if(CINE||e.repeat||e.ctrlKey||e.metaKey||e.altKey||document.querySelector('.qfx,.yrfx'))return;
  const t=e.target;if(t&&/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))return;
  const tf=document.querySelector('.turnfx');if(tf){tf.remove();if(!/^[1-9]$/.test(e.key))return;}
  if(/^[1-9]$/.test(e.key)){const b=document.querySelectorAll('#gOpts .opt')[+e.key-1];if(b&&!b.disabled){e.preventDefault();b.click();}return;}
  if(e.key==='Enter'||e.key===' '){const n=document.getElementById('nx');if(n&&(!t||t.tagName!=='BUTTON'||t===n)){e.preventDefault();n.click();}}});
function reroll(){if(tok<=0)return;SVAT=null;SFX.rewind();tok--;RUN.rr++;{const _l=LOG[LOG.length-1];if(_l)_l.rerolls++;}useSnap();tally[lastT]--;yTally[lastT]--;CAR.tt[lastT]--;const t2=roll(lastFit.q,lastS);lastT=t2;tally[t2]++;yTally[t2]++;CAR.tt[t2]++;
  R.innerHTML='<div id="wrap" style="position:relative;min-height:260px">'+vign()+'<div class="g-hud">'+hud()+'</div>'+
  '<div class="g-main" style="font-size:13px;color:var(--text-muted);text-align:center;margin-top:24px">운명의 주사위를 다시 굴린다</div>'+
  '<div id="fx" style="position:absolute;inset:-6px;display:flex;align-items:center;justify-content:center;pointer-events:none"></div></div>';
  bindSnd();reel(t2,()=>resolve(lastO,t2));}

function resolve(o,t){const e=o[1],ch=o[3];logTier(t);
  chron.push({t:t,n:cur.t});hist.push(t);streak=(t<=1)?streak+1:0;
  if(e.X==='crush'){const able=(S.p>52&&S.a>32);
    if(t===3||(!able&&t!==0))return gate('ousted');
    apply({u:-30,a:-22,c:11,p:6},1);
    last={t:t,x:'공권력이 광장을 비웠다. 질서는 돌아왔고 <em>그 장면이 정부의 얼굴</em>이 됐다. '+pk(TIER[t].l)};}
  else if(e.X==='quit'){S.quit=1;return careerEnd('quit');}
  else{apply(e,0,t,STK[lastS]);last={t:t,x:o[2]+' '+pk(TIER[t].l),cn:cnBonus(e,t).concat(cnSaveMsg?[cnSaveMsg]:[])};cnSaveMsg='';
    if(t===3){S.a=cl(S.a-4);S.u=cl(S.u+4);}
    if(lastS===2&&t===0){S.a=cl(S.a+4);last.x+=' <em>승부수가 통했다.</em> 결단력 있는 지도자라는 평가가 붙었다.';CAR.boldWin=(CAR.boldWin||0)+1;}
    if(lastS===2&&t===3){S.a=cl(S.a-2);S.u=cl(S.u+2);last.x+=' <em>무리수였다</em>는 비판이 쏟아졌다.';CAR.boldLoss=(CAR.boldLoss||0)+1;}
    if(ch){const id=t<=1?ch.ok:ch.bad;if(id&&CH[id])queue.push(CH[id]);}
    if(cur.sp&&spAct(o[4],t)==='coupfail')return breaking({k:'bad',h:'계엄 해제 요구안 가결… 내란 실패',s:'계엄군 철수, 대통령 관저 앞에 시민 수만 명',b:'군은 끝내 국회 진입 명령을 따르지 않았다. 내란 혐의 수사가 시작됐고, 정권은 그날 밤으로 끝났다.'},()=>careerEnd('coupfail'));
    pathAfter(e);}
  for(let k=0;k<TPT;k++)tick();
  TH.push({a:S.a,i:S.i,h:vVal('H')});logAfter();MAP.tgt=S.i;MAP.dtgt=deaths;
  if(S.m<=3&&S.i>=75)return gate('medfail');
  if(S.e<=4)return gate('ecofail');
  if(S.a<=3&&S.u>=68)return gate('ousted');
  res();}

// 선택이 쌓이면 노선이 생기고, 노선마다 다른 후속 사건이 1·2단계로 이어진다 (임기마다 새로 센다)
function pathAfter(e){if(!CAR.path)return;const d=dirOf(e)[0],pr=priOf(e);
  if(d>=5)CAR.path.hard++;if(d<=-5)CAR.path.soft++;if(pr==='경제'||(e.e||0)>=5)CAR.path.eco++;
  const sid=sidNow(),T1=PY>=6?3:2,T2=PY>=6?6:4,P=PATHS[sid];if(!P)return;
  for(const k of ['hard','soft','eco']){const n=CAR.path[k],st=CAR.pstage[k]||0;
    const want=n>=T2&&st===1?2:n>=T1&&st===0?1:0;
    if(want&&!queue.some(x=>x.path)){queue.push(P[k][want-1]);CAR.pstage[k]=want;CAR.pathLog.push(CAR.term+'기 '+PATHN[k]+' '+want+'단계');break;}}}
function gate(kind){SVAT=null;if(tok<=0)return careerEnd(kind);SFX.gate();vib([120,80,160]);
  R.innerHTML='<div style="animation:fdIn .5s ease-out;position:relative"><div style="position:absolute;inset:-6px;pointer-events:none;border-radius:12px;background:radial-gradient(ellipse at center,transparent 40%,rgba(179,38,30,.35) 100%)"></div>'+
  '<div style="font-size:12.5px;font-weight:700;color:var(--text-danger);letter-spacing:.04em;margin-bottom:8px;animation:pls 1.4s infinite">정권의 마지막 순간</div>'+
  '<div style="font-size:24px;font-weight:600;margin-bottom:12px">이대로 끝인가?</div>'+
  '<div style="font-size:14px;color:var(--text-secondary);line-height:1.8;margin-bottom:22px">역사가 이 정권의 마지막 문장을 쓰기 직전이다. 아직 <em>운명에 개입할 기회</em>가 '+tok+'번 남아 있다. 다시 굴려도 같은 결과가 나올 수 있다.</div>'+
  '<button id="rr" style="width:100%;margin-bottom:8px;padding:13px"><span style="color:#2f4a6b">●</span>&nbsp; 운명에 개입한다 (남은 '+tok+'회)</button>'+
  '<button id="ac" style="width:100%;font-size:13px;color:var(--text-secondary)">운명을 받아들인다</button></div>';
  document.getElementById('rr').onclick=reroll;document.getElementById('ac').onclick=()=>{SFX.fade();careerEnd(kind);};}

// 영구집권(계엄) 상태에서는 지지율이 떨어질 때 DICT_AK배로 더 크게 떨어진다
const DICT_AK=1.5;
function apply(e,raw,t,M){const T=TIER[t===undefined?1:t],mom=streak>=4?1.1:1;M=M||STK[1];
  for(const k in e){if(k==='X')continue;const v=e[k],good=BAD[k]?v<0:v>0;let d=raw?v:v*EVS*(good?M.g*T.g*mom:M.b*T.b);
    if(k==='a'&&d<0&&CAR&&CAR.dict)d*=DICT_AK;S[k]=cl(S[k]+d);}}

// 한 번 호출 = 1개월. 결정 빈도와 상관없이 1년에 12번 돈다. 임기가 거듭될수록(TD) 확산·피해·부패 압력이 커지고 지지율은 더 빨리 빠진다.
function tick(){const te=MOD.te||1,D=DIFF[dif],yr=Math.floor(S.turn/PY),TD=(CAR.term-1)*(CP.tdk||1);
  let r=.18+S.u/500+(MOD.ip||0)+yr*.022+D.r+TD*.02+(TD===0&&yr>=2?.015:0)-S.p/330-(S.trn*te)/900-S.m/1100;r=Math.max(-.11,Math.min(.36,r));
  S.i=cl(Math.max(D.fl+(TD>0?2+2*TD:0),S.i+S.i*r*(1-S.i/100)));if(S.i>peakI)peakI=S.i;
  S.m=cl(S.m-Math.max(0,S.i-50)/13+S.e/150+.2+(CP.mk||0));
  const dd=(S.i/28)*(1+Math.max(0,50-S.m)/42)*(MOD.dd||1)*D.dd*(1+TD*.2);deaths+=dd;yd+=dd;cDeaths+=dd;if(TD===0)covD+=dd*320*(yr===0?Math.min(1,Math.pow((S.turn+.3)/PY,2)):1);
  S.e=cl(S.e-S.i/72-S.p/170+S.saf/210+.48+(MOD.ep||0)-S.c/62+(TD>0?SCX().eb||0:0));
  S.c=cl(S.c+.22+TD*.07+Math.max(0,S.p-34)/22*(1-(S.trn*te)/150)-(S.trn*te)/320);
  S.u=cl(S.u+S.i/95+Math.max(0,S.p-45)/47+Math.max(0,45-S.e)/58-S.saf/230-.32+(MOD.up||0));
  const a0=S.a;S.a=cl(S.a-.32-D.ad-TD*.06-Math.max(0,S.a-55)/65+Math.max(0,S.p-40)/260*(S.i>40?1:0)-S.i/85-Math.max(0,48-S.e)/62-S.u/130-S.c/160+Math.max(0,S.e-55)/95+(MOD.ap||0));
  if(CAR&&CAR.dict&&S.a<a0)S.a=cl(a0-(a0-S.a)*DICT_AK);
  S.p=cl(S.p-S.chk/100*(S.p/115));
  S.chk=cl(S.chk-.12-TD*.03-Math.max(0,S.p-45)/70);S.trn=cl(S.trn-.1-S.c/260);S.saf=cl(S.saf-.08);
  S.mil=cl((S.mil==null?50:S.mil)-.11+(S.e-50)/1500);
  if(CAR&&CAR.endemic===CAR.term)S.i=Math.min(S.i,10);}

let KN={a:'지지율',i:'확산',m:'의료',e:'경제',p:'행정 권한',c:'유착',u:'갈등',chk:'견제',trn:'투명성',saf:'안전망',mil:'군사'};
function deltas(){if(!snap)return '';
  const ch=VORD.map(k=>[k,vVal(k,S)-vVal(k,snap.S)]).filter(x=>Math.abs(x[1])>=1.5);
  return ch.map(([k,d],j)=>{const g=vGood(k,d),col=g===null?'#3d5a80':g?'#2e7d55':'#b3261e',n=Math.round(d);
    return '<span style="display:inline-flex;align-items:center;gap:5px;font-size:12px;padding:4px 9px;border-radius:999px;background:color-mix(in srgb,'+V6[k].col+' 16%,var(--surface-1));border:1px solid color-mix(in srgb,'+V6[k].col+' 45%,transparent);margin:0 5px 5px 0;opacity:0;animation:fdIn .3s ease-out forwards;animation-delay:'+(j*70)+'ms">'+vName(k)+' <b style="color:'+col+';font-size:12px">'+(n>0?'+':'')+n+'</b></span>';}).join('');}

function res(){const T=TIER[last.t],wc=last.x.split(' ').length,dl=Math.min(650,wc*22+120);
  sbFrom=snap&&snap.S;const hh=hud();sbFrom=null;
  R.innerHTML='<div id="wrap" class="fit" style="position:relative">'+vign()+'<div class="g-hud">'+hh+sideHTML()+'</div><div class="g-main"><div class="g-sc">'+
  '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px"><span class="tierb" style="font-size:12.5px;padding:3px 10px;border-radius:999px;background:'+T.tint+';color:'+T.fg+';font-weight:700">'+T.n+'</span><span style="font-size:12.5px;color:var(--text-muted);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+cur.t+'</span></div>'+
  tip('result')+(tok>0&&last.t>=2&&!cur.mg?tip('reroll'):'')+
  '<div id="txt" style="background:color-mix(in srgb,'+T.bd+' 7%,var(--surface-2));border:1px solid color-mix(in srgb,'+T.bd+' 32%,transparent);border-radius:14px;padding:16px 17px;margin-bottom:14px;cursor:pointer"><div class="rsd" style="font-size:15.5px;line-height:1.85">'+words(last.x,40)+'</div></div>'+
  '<div style="margin-bottom:12px;min-height:28px">'+deltas()+'</div>'+
  (last.cn&&last.cn.length?'<div class="cn-fx">'+last.cn.map(x=>'<span>'+x+'</span>').join('')+'</div>':'')+
  (()=>{if(cur.mg)return '<div class="jdg"><span>판정</span><b>경기 결과로 정해졌다</b></div>';
  if(spFixed(lastO))return '<div class="jdg"><span>판정</span><b>'+(lastO[4].vote?'투표로':'거사 결과로')+' 정해졌다</b></div>';const fw=fitWord(lastFit.q),P=stakeP(lastFit.q,lastS);return '<div class="jdg"><span>판정</span><span class="stk s'+lastS+'">'+STK[lastS].n+'</span><b style="color:'+fw[1]+'">'+fw[0]+'</b><span class="jdg-p">성공 이상 '+Math.round((P[0]+P[1])*100)+'%</span></div>';})()+
  (lastFit.why.length?'<div style="font-size:12px;font-weight:600;color:var(--text-muted);margin-bottom:6px">판정에 영향을 준 것</div><div style="display:flex;flex-direction:column;gap:5px;margin-bottom:18px">'+lastFit.why.map((w,j)=>'<div style="font-size:13px;color:var(--text-secondary);opacity:0;animation:fdIn .3s ease-out forwards;animation-delay:'+(200+j*90)+'ms"><b style="color:'+(w[0]==='+'?'#2e7d55':'#b3261e')+'">'+(w[0]==='+'?'▲':'▼')+'</b> '+w[1]+'</div>').join('')+'</div>':'<div style="height:4px"></div>')+
  '</div><div class="g-bt">'+
  '<button id="nx" class="late pri" style="width:100%;margin-bottom:8px;padding:14px;font-size:15px;opacity:0;animation:fdIn .3s ease-out forwards;animation-delay:'+dl+'ms">계속</button>'+
  (tok>0&&last.t>=2&&!cur.mg&&!(cur.sp&&lastO&&lastO[4])?'<button id="rr" class="late" style="width:100%;font-size:13.5px;font-weight:600;color:#3d5a80;border-color:rgba(47,74,107,.45);background:rgba(47,74,107,.08);display:flex;align-items:center;justify-content:center;gap:8px;opacity:0;animation:fdIn .3s ease-out forwards;animation-delay:'+(dl+120)+'ms"><span class="dots"><i></i></span>운명에 개입한다 (남은 '+tok+'회)</button>':'')+
  '<div class="rs-hint" style="text-align:center;font-size:12px;color:var(--text-muted);margin-top:8px">글을 누르면 바로 넘길 수 있다</div></div></div></div>';
  bindSnd();fitP();
  const w=document.getElementById('wrap');document.getElementById('txt').onclick=()=>{w.classList.add('skip');};
  document.getElementById('nx').onclick=()=>{SFX.click();goNext();};SVAT='nx';
  const r=document.getElementById('rr');if(r)r.onclick=reroll;}

// 결과 화면의 '계속': 다음 결정으로, 해가 끝났으면 연간 결산으로
function goNext(){S.turn++;if(S.turn%PY===0)return report();next();pickAdv();ev();}
function next(){bnSeen=null;if(queue.length){cur=queue.shift();if(cur.sg)cur=spGen(cur.sg);return;}
  {const L=(MILEV[CP.id]||[]).filter(e=>!SEEN.has(e.t));if(L.length&&Math.random()<.11){cur=pk(L);SEEN.add(cur.t);return;}}
  if(S.u>44&&Math.random()<Math.pow(S.u/100,2)*(.35+S.c/110)*(1-S.chk/180)*.22*(cnHas('upr')?.5:1)){cur=(S.chk>=48&&CP.id!=='joseon')?IMP:UPR;return;}
  const y=Math.floor(S.turn/PY)+1,T=CAR.term;
  const sid=sidNow(),late=CP.rule==='single'&&y>=3;
  const okf=e=>(e.sc?e.sc===sid:(e.y===0||sid===CP.scen0))&&(e.y===0||e.y===y)&&(!e.tm||T>=e.tm||late)&&(!e.w||e.w(S))&&!(SKIN[e.t]&&SKIN[e.t].no&&SKIN[e.t].no.indexOf(sid)>=0);
  // 한 커리어에서 같은 사건은 다시 나오지 않는다. 그 위기의 사건을 다 봤을 때만 가장 오래전에 본 사건을 다시 꺼낸다.
  // 위기마다 모습이 다른 공통 사건은 그 모습(제목)으로 따로 센다
  const key=e=>{const k=SKIN[e.t]&&SKIN[e.t][sid];return k&&k.t?k.t:e.t;};
  let ok=pool.filter(okf);
  // 지표가 선에 닿아 생긴 사건은 먼저 나올 가능성이 크다
  const stv=ok.filter(e=>e.st&&!SEEN.has(key(e)));if(stv.length&&Math.random()<.45)ok=stv;
  const fresh=ok.filter(e=>!SEEN.has(key(e)));
  if(fresh.length)ok=fresh;else{const all=CP.ev.filter(okf);const old=all.filter(e=>SEEN.has(key(e))).sort((a,b)=>(SEENT[key(a)]||0)-(SEENT[key(b)]||0));ok=old.slice(0,Math.max(1,Math.ceil(old.length/3)));}
  if(T>=2||late){const te=ok.filter(e=>e.tm);if(te.length&&Math.random()<.3+.08*Math.max(0,T-2))ok=te;}
  if(!ok.length){pool=CP.ev.slice();ok=pool.filter(okf);}
  const pick=pk(ok);if(pool.indexOf(pick)>=0)pool.splice(pool.indexOf(pick),1);SEEN.add(key(pick));SEENT[key(pick)]=++SEENN;cur=skinOf(pick,sid);}

function score(){const ins=Math.max(0,(S.chk+S.trn+S.saf)-base),ds=cl(100-deaths/2.2);
  return S.a*.26+ds*.27+S.e*.19+(100-S.c)*.11+Math.min(100,ins*1.25)*.17;}

/* ---------- CHARTS (숫자 없이) ---------- */
function bars(rows){return rows.map((r,k)=>{const v=Math.round(cl(r.v)),pv=r.pv==null?null:Math.round(cl(r.pv));
  const gv=r.bad?100-v:v,col=r.neu?'#2f4a6b':gv>=66?'#2e7d55':gv>=40?'#9a6400':'#b3261e';
  const d=pv==null?0:v-pv,up=r.bad?d<=-3:d>=3,dn=r.bad?d>=3:d<=-3,ar=d>=3?'▲':d<=-3?'▼':'–',ac=r.neu?'#3d5a80':up?'#2e7d55':dn?'#b3261e':'var(--text-muted)';
  return '<div style="display:flex;align-items:center;gap:10px;margin-bottom:9px"><span style="width:62px;font-size:12px;color:var(--text-secondary);flex-shrink:0">'+r.n+'</span>'+
  '<span style="position:relative;flex:1;height:10px;border-radius:5px;background:rgba(29,27,24,.06)">'+
  '<span style="position:absolute;left:0;top:0;bottom:0;width:'+v+'%;border-radius:5px;background:'+col+';animation:barG .9s cubic-bezier(.2,.8,.2,1) both;animation-delay:'+(k*55)+'ms"></span>'+
  (pv!=null?'<span style="position:absolute;top:-3px;bottom:-3px;left:calc('+pv+'% - 1px);width:2px;background:rgba(29,27,24,.6);border-radius:1px"></span>':'')+
  '</span><span style="width:14px;font-size:11px;text-align:center;color:'+ac+'">'+ar+'</span></div>';}).join('');}
// 세로 화면 결산용 지표 타일: 값과 작년 대비 변화(좋아지면 초록, 나빠지면 빨강)
function tiles(rows){return '<div class="rp-tl">'+rows.map(r=>{const v=Math.round(cl(r.v)),pv=r.pv==null?null:Math.round(cl(r.pv)),d=pv==null?0:v-pv;
  const gv=r.bad?100-v:v,col=r.neu?'#2f4a6b':gv>=66?'#2e7d55':gv>=40?'#9a6400':'#b3261e',good=r.bad?d<0:d>0,dc=r.neu?'#3d5a80':!d?'var(--text-muted)':good?'#2e7d55':'#b3261e';
  return '<div class="rp-t" style="--c:'+r.c+'"><span>'+r.n+'</span><b style="color:'+col+'">'+v+'</b><i style="color:'+dc+'">'+(d>0?'▲'+d:d<0?'▼'+(-d):'–')+'</i></div>';}).join('')+'</div>';}
function lineChart(series,n){const W=300,H=100,P=5,X=i=>P+i*(W-2*P)/n,Y=v=>P+(100-v)*(H-2*P)/100;
  let s='<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;height:auto;display:block" aria-hidden="true">';
  for(let y=1;y<YRS;y++){const x=X(y*PY).toFixed(1);s+='<line x1="'+x+'" x2="'+x+'" y1="0" y2="'+H+'" stroke="rgba(29,27,24,.06)"/>';}
  [35,65].forEach(v=>{s+='<line x1="'+P+'" x2="'+(W-P)+'" y1="'+Y(v)+'" y2="'+Y(v)+'" stroke="rgba(29,27,24,'+(v===35?.4:.22)+')" stroke-dasharray="3 4"/>';});
  series.forEach(se=>{if(se.pts.length<2)return;const d=se.pts.map((v,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(v).toFixed(1)).join(' ');
    s+='<path d="'+d+'" fill="none" stroke="'+se.col+'" stroke-width="'+se.w+'" stroke-linejoin="round" stroke-linecap="round" pathLength="1" style="stroke-dasharray:1;stroke-dashoffset:1;animation:drawL 1.1s ease-out forwards"/>';
    const j=se.pts.length-1;s+='<circle cx="'+X(j).toFixed(1)+'" cy="'+Y(se.pts[j]).toFixed(1)+'" r="3.2" fill="'+se.col+'"/>';});
  return s+'</svg>';}
function dirByYear(){const ys=[];LOG.forEach(x=>{if(x.eventType==='임기 결정')return;(ys[x.cyear-1]=ys[x.cyear-1]||[]).push(x.dirScore);});
  const out=[];for(let i=0;i<ys.length;i++){const a=ys[i]||[];out.push(a.length?a.reduce((p,q)=>p+q,0)/a.length:0);}return out;}
function powerChart(){const v=dirByYear(),n=Math.max(v.length,1),W=300,H=128,mid=64,bw=(W-10)/n,sc=v2=>Math.max(-1,Math.min(1,v2/14))*54;
  let s='<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;height:auto;display:block" aria-hidden="true">';
  s+='<line x1="4" x2="'+(W-4)+'" y1="'+mid+'" y2="'+mid+'" stroke="rgba(29,27,24,.25)"/>';
  for(let t=1;t*YRS<n;t++){const x=(5+t*YRS*bw).toFixed(1);s+='<line x1="'+x+'" x2="'+x+'" y1="4" y2="'+(H-4)+'" stroke="rgba(29,27,24,.12)" stroke-dasharray="2 3"/>';}
  for(let t=0;t*YRS<n;t++){s+='<text x="'+(7+t*YRS*bw).toFixed(1)+'" y="12" font-size="9" fill="rgba(29,27,24,.45)">'+(t+1)+'기</text>';}
  v.forEach((d,i)=>{const h=sc(d),x=5+i*bw+bw*.18,w=bw*.64,y=h>=0?mid-h:mid,col=h>=0?'#b3261e':'#2f5f99';
    s+='<rect x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+w.toFixed(1)+'" height="'+Math.max(1.5,Math.abs(h)).toFixed(1)+'" rx="2" fill="'+col+'" style="transform-origin:'+(x+w/2).toFixed(1)+'px '+mid+'px;animation:upY .6s cubic-bezier(.2,.8,.2,1) both;animation-delay:'+(i*45)+'ms"/>';});
  return s+'</svg>';}
const sbar=(n,v,mx,col,sub,k)=>'<div style="margin-top:8px"><div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px"><span><b>'+n+'</b> <span style="color:var(--text-muted)">'+sub+'</span></span><span style="font-weight:600">'+v+' <span style="color:var(--text-muted);font-weight:400">/ '+mx+'</span></span></div>'+
  '<div style="height:8px;border-radius:4px;background:rgba(29,27,24,.07);overflow:hidden"><div style="height:100%;width:'+Math.max(0,Math.min(100,v/mx*100))+'%;background:'+col+';border-radius:4px;animation:barG .9s cubic-bezier(.2,.8,.2,1) both;animation-delay:'+(500+k*120)+'ms"></div></div></div>';
const chip=(t,col,ex)=>'<span style="display:inline-block;font-size:12px;font-weight:600;padding:4px 10px;border-radius:999px;margin:0 6px 6px 0;background:color-mix(in srgb,'+col+' 14%,var(--surface-1));border:1px solid color-mix(in srgb,'+col+' 45%,transparent);'+(ex||'')+'">'+t+'</span>';

/* ---------- 연간 결산 ---------- */
function report(){SFX.report();window.scrollTo(0,0);
  const y=S.turn/PY,fin=S.turn>=YRS*PY,sc=score();let tr='';
  if(prev!==null){const d=sc-prev;tr=d>3?'전체적으로 작년보다 나아지고 있습니다.':d<-3?'솔직히 말씀드리면, <em>작년보다 나빠지고 있습니다</em>.':'작년과 크게 다르지 않습니다.';}
  prev=sc;
  const earned=TRO.filter(t=>{try{return t.c();}catch(e){return false;}}).sort((a,b)=>b.g-a.g).filter((t,j,arr)=>t.g?arr.filter(z=>z.g).indexOf(t)<2:true);
  earned.forEach(t=>CAR.tro.push({id:t.id,n:t.n,g:t.g,term:CAR.term,year:y}));
  CAR.cs.push(S.c);CAR.ts.push(S.trn);CAR.us.push(S.u);CAR.ss.push(S.saf);
  const X=SCX(),hs=hudStats();
  const tro=earned.length?earned.map((t,j)=>chip((t.g?'업적 · ':'불명예 · ')+t.n,t.g?'#2e7d55':'#b3261e','animation:reelIn .4s cubic-bezier(.2,1.4,.4,1) both;animation-delay:'+(300+j*120)+'ms;font-weight:600;color:'+(t.g?'#2a6e4b':'#a8321f'))).join(''):'<span style="font-size:12px;color:var(--text-muted)">올해는 특별한 기록이 없다.</span>';
  const P=YS,vr=k=>({n:vName(k),v:vVal(k,S),pv:vVal(k,P),bad:V6[k].pol<0,neu:V6[k].pol===0,c:V6[k].col}),rows=['A','E','H','M'].map(vr);
  const pw=['P','X'].map(vr);
  const cr=chron.map(c=>chip(c.n,TIER[c.t].bd)).join('');
  const worst=[['i',100-S.i],['m',S.m],['a',S.a],['e',S.e],['u',100-S.u],['c',100-S.c]].sort((a,b)=>a[1]-b[1])[0][0];
  const say=RPX(worst)[bd(S[worst])];
  // 세로 화면: 지표는 3×2 타일, 흐름 그래프는 같은 카드에 낮게, 다음 버튼은 아래 고정(pfit)
  const PO=isP(),chart=lineChart([{pts:TH.map(h=>h.h!=null?h.h:100-h.i),col:V6.H.col,w:1.6},{pts:TH.map(h=>h.a),col:'#2e7d55',w:2.4}],YRS*PY),
    legend='<div style="display:flex;gap:14px;font-size:11px;color:var(--text-muted);margin-top:8px;flex-wrap:wrap"><span><b style="color:#2e7d55">━</b> '+KN.a+'</span><span><b style="color:'+V6.H.col+'">━</b> '+X.ctrl+'</span><span>'+(CP.rule==='reign'?'┄ 반정 위험선 35 · 안정 65':'┄ 출마선 35 · 당선 확정 65')+'</span></div>';
  R.innerHTML='<div class="'+(PO?'pfit rp':'')+'" style="position:relative;animation:fdIn .35s ease-out">'+(PO?'<div class="p-sc">':'')+
   '<div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px"><span style="font-size:12px;font-weight:600;color:var(--text-muted)">'+(CP.id==='joseon'?CAR.term+'번째 치세':CAR.term+'기')+' '+y+'년차 연말 · '+ageNow()+'세</span><span style="font-size:11px;color:var(--text-muted)">'+MOD.n+'</span></div>'+
   '<div class="hd rp-h" style="font-size:24px;margin-bottom:8px">'+(fin?'임기 마지막 결산':'연간 총결산')+'</div>'+
   '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px"><span style="font-size:11px;padding:4px 9px;border-radius:999px;background:rgba(179,38,30,.14);color:#a8321f;font-weight:600">'+(isCov()?(y>=3?'신종 변이':'코로나19'):X.n)+'</span>'+
   hs.map(q=>'<span style="font-size:11px;padding:4px 9px;border-radius:999px;background:var(--surface-1);color:var(--text-secondary)">'+q[0]+' <b style="color:var(--text-primary)">'+fmtStat(q)+'</b></span>').join('')+'</div>'+
   tip('report')+card(lab('올해의 기록')+tro)+
   (PO?card(lab('국정 지표 · 작년 대비')+tiles(rows.concat(pw))+'<div class="rp-ch">'+chart.replace('<svg ','<svg preserveAspectRatio="none" ')+'</div>'+legend):
   card(lab('국정 지표 · 흰 눈금은 작년')+bars(rows)+'<div style="height:1px;background:var(--border);margin:6px 0 12px"></div>'+bars(pw)+
     '<div style="font-size:11px;color:var(--text-muted);line-height:1.6;margin-top:4px">'+vName('P')+'이 크면 일이 빨라지지만 견제가 사라지고 '+vName('X')+'도 함께 자란다.</div>')+
   card(lab('임기 흐름')+chart+legend))+
   '<div style="display:flex;gap:10px;align-items:flex-start;margin:4px 4px 14px">'+(cnHired()[0]?portrait(cnHired()[0].n,30):'')+
   '<div style="font-size:13px;line-height:1.7;color:var(--text-secondary)">'+(cnHired()[0]?'<b style="color:var(--text-primary)">'+cnHired()[0].n+'</b> ':'')+'<span style="font-family:var(--font-voice)">"'+say+(tr?' '+tr:'')+'"</span></div></div>'+
   lab('그해의 결정들')+'<div style="margin-bottom:18px">'+cr+'</div>'+(PO?'</div><div class="p-bt">':'')+
   '<button id="nx" class="pri" style="width:100%;padding:15px;font-size:15px">'+(fin?'임기 만료':(y+1)+'년차로')+'</button></div>'+(PO?'</div>':'');
  CAR.yrs.push(yearSnap(y,earned,1));bindTips();pMore();
  const ny=y+1,varN=!fin&&CP.id==='kr'&&CAR.term===1&&ny===3&&CAR.endemic!==CAR.term;
  chron=[];yd=0;yTally=[0,0,0,0];YS=Object.assign({},S);
  // 해가 바뀔 때는 금장 셔터로 넘어간다
  document.getElementById('nx').onclick=()=>{SFX.click();const tl=CP.id==='joseon'?CAR.term+'번째 치세':CAR.term+'기';
    if(fin)return yearFx(tl+' 임기 만료','이 임기의 성적표가 나왔다',termEnd);
    yearFx(tl+' '+ny+'년차',leaderQ(careerYear(ny))||'새해가 밝았다',()=>council(()=>spBoard(()=>{if(varN)variantHit();else{if(CAR.term>=2)waveHit();next();}pickAdv();ev();})));};}

/* ---------- 임기 평가 · 연임 ---------- */
const ENDS={ousted:['거리로 쫓겨난 대통령','여론과 광장이 정권을 먼저 끝냈다. 위기 대응의 성패를 따지기도 전에 정부가 사라졌다.','#b3261e'],
medfail:['의료 붕괴','병상도 인력도 남지 않았다. 이 시기의 사망자 수는 이후 어떤 통계에서도 정상으로 분류되지 않는다.','#b3261e'],
ecofail:['무너진 경제','위기는 어떻게든 버텼다. 사람들이 돌아갈 일자리가 남지 않았을 뿐이다.','#b8541e']};
const r1=v=>Math.round(v*10)/10;
// 임기 점수 = 지지율×0.26 + 생명 보호×0.27 + 경제×0.19 + 청렴(100−유착)×0.11 + 제도 변화×0.17
function scoreParts(){const ins=Math.max(0,(S.chk+S.trn+S.saf)-base),life=cl(100-deaths/2.2),inst=Math.min(100,ins*1.25);
  return {a:r1(S.a*.26),life:r1(life*.27),eco:r1(S.e*.19),clean:r1((100-S.c)*.11),inst:r1(inst*.17),lifeScore:r1(life),instScore:r1(inst)};}
function choiceStats(N){const avg=a=>a.length?r1(a.reduce((p,q)=>p+q,0)/a.length):'';
  return {nCh:N.length,nConc:N.filter(z=>z.direction==='권력 집중').length,nDisp:N.filter(z=>z.direction==='견제·분산').length,nNeut:N.filter(z=>z.direction==='중립').length,avgDir:avg(N.map(z=>z.dirScore))};}
function yearSnap(y,earned,done){const N=LOG.filter(z=>z.term===CAR.term&&z.year===y&&z.eventType!=='임기 결정');
  const hs=hudStats();
  return Object.assign({term:CAR.term,year:y,scenario:y>=3&&isCov()?'신종 변이':isCov()?'코로나19':SCX().n,disp1:hs[0][0]+' '+fmtStat(hs[0]),disp2:hs[1]?hs[1][0]+' '+fmtStat(hs[1]):'',cyear:(CAR.term-1)*YRS+y,age:CAR.age0+(CAR.term-1)*YRS+y-1,done:done?'예':'아니오(중간에 끝남)',
    score:r1(score()),grade:grade(score()),yd:Math.round(yd),cDeaths:Math.round(cDeaths),
    troGood:earned.filter(t=>t.g).map(t=>t.n).join(', '),troBad:earned.filter(t=>!t.g).map(t=>t.n).join(', '),
    dice0:yTally[0],dice1:yTally[1],dice2:yTally[2],dice3:yTally[3]},stNow(),choiceStats(N));}
// 진행 중이던 해에 이미 고른 선택이 있으면 그 해를 '중간에 끝남'으로 남긴다
function partialYear(){const y=Math.floor(S.turn/PY)+1;return y<=YRS&&!CAR.yrs.some(z=>z.term===CAR.term&&z.year===y)&&LOG.some(z=>z.term===CAR.term&&z.year===y)?y:0;}
function evalTerm(kind){
  const ins=Math.max(0,(S.chk+S.trn+S.saf)-base);
  let sc=score();if(kind==='quit')sc-=6;const auth=(S.p>=60&&S.chk<=44),g=grade(sc);
  let eid,ti,ds,col;
  if(ENDS[kind]){eid=kind;ti=ENDS[kind][0];ds=ENDS[kind][1];col=ENDS[kind][2];}
  else if(kind==='quit'){eid='quit';ti='임기를 채우지 못한 대통령';ds='스스로 내려왔다. 그 판단이 옳았는지는 오래 논쟁거리로 남는다.';col='#6e675c';}
  else if(S.c>=60&&S.a>=48){eid='shadow';ti='그림자 정부';ds='유착은 극에 달했는데 지지율은 무너지지 않았다. <em>부패한 정부가 사랑받을 수 있다</em>는 가장 불편한 증명이 됐다.';col='#b3261e';}
  else if(deaths<34&&S.e>=60&&peakI<=45){eid='kmyth';ti=wd('기적의 방역','기적 같은 위기 극복');ds='사람도 지키고 경제도 지켰다. 다른 나라들은 <em>둘 중 하나는 포기해야 했다</em>.';col='#2e7d55';}
  else if(S.trn>=86&&ins>=20){eid='science';ti='과학이 이겼다';ds='이 정부의 무기는 권한이 아니라 <em>공개된 데이터</em>였다. 사람들은 명령이 아니라 근거를 따라 움직였다.';col='#2f5f99';}
  else if(S.a>=58&&S.e>=58&&S.m>=58&&S.i<=25&&S.c<=28&&S.u<=35){eid='balance';ti='완벽한 균형';ds='방역, 경제, 의료, 여론, 청렴. <em>무엇 하나 버리지 않았다</em>. 교과서는 이런 사례를 오래 찾고 있었다.';col='#2f4a6b';}
  // 히든 엔딩 추가분: 운(대성공 비율), 청렴(유착 바닥 + 높은 투명성), 극한의 혼란 속 완주
  else if((()=>{const n=CAR.tt.reduce((a,b)=>a+b,0);return n>=8&&CAR.tt[0]>=Math.max(4,n*.34);})()){eid='lucky';ti='하늘이 내린 운';ds='판정 주사위가 이상할 만큼 <em>당신 편이었다</em>. 실력이었는지 운이었는지는 아무도 모른다. 본인도.';col='#8f6a12';}
  else if(S.c<=3&&S.trn>=78){eid='clean';ti='맑은 물의 정부';ds='뒷돈 한 푼, 감춘 문서 한 장 없었다. <em>털어도 먼지가 나지 않는</em> 정부를 사람들은 처음 보았다.';col='#1f7a72';}
  else if(S.u>=70&&S.c>=50){eid='storm';ti='폭풍 속의 생존자';ds='나라는 갈라졌고 권력 주변은 썩었다. 그런데도 <em>임기를 끝까지 채웠다</em>. 어떻게 버텼는지는 회고록에도 나오지 않는다.';col='#a8406f';}
  else if(auth&&sc<70){eid='auth';ti='권위주의로 돌아선 대통령';ds='위기를 이유로 얻은 권한을 끝내 돌려주지 않았다. <em>다음 대통령도 그 권한을 쓴다.</em>';col='#b3261e';}
  else if(ins>=28&&S.a>=45){eid='inst';ti='제도를 남긴 대통령';ds='개인의 판단이 아니라 <em>구조를 바꿨다</em>. 다음 '+wd('팬데믹','위기')+'에 이 나라가 덜 다친다면 그건 이 임기 덕분이다.';col='#2f4a6b';}
  else if(sc>=80){eid='legend';ti='역사에 남을 대응';ds='세계가 이 나라의 사례를 인용했다. 그리고 실제로 사람이 덜 죽었다.';col='#2e7d55';}
  else if(sc>=66){eid='reelect';ti='신임받은 대통령';ds='완벽하지 않았지만 국민은 이 정부를 믿었다.';col='#2e7d55';}
  else if(sc>=52){eid='modest';ti='무난히 임기를 마친 대통령';ds='큰 실패도 큰 성취도 없었다. '+wd('팬데믹','위기의')+' 시대 대통령에게 이것이 나쁜 성적인지는 애매하다.';col='#2f5f99';}
  else if(sc>=36){eid='judged';ti='심판받은 대통령';ds='사람들은 이 '+YRS+'년을 되도록 이야기하지 않으려 한다.';col='#6e675c';}
  else{eid='failfp';ti=wd('실패한 방역','실패한 위기 대응');ds='막을 수 있었던 '+wd('죽음','피해')+'이 너무 많았다. 그것이 이 임기에 대한 유일한 요약이다.';col='#b3261e';}
  const N=LOG.filter(z=>z.term===CAR.term&&z.eventType!=='임기 결정');
  return Object.assign({term:CAR.term,scenario:termScn(),elect:'',winP:'',kind:kind,eid:eid,ti:ti,ds:ds,col:col,sc:sc,g:g,ins:ins,auth:auth,peakI:Math.round(peakI),deaths:Math.round(deaths),
    decision:'',months:Math.min(YRS*12,Math.round(S.turn*12/PY)),ageStart:CAR.age0+(CAR.term-1)*YRS,ind:stNow(),cDeaths:Math.round(cDeaths),
    parts:scoreParts(),dice:CAR.tt.slice(),troG:CAR.tro.filter(t=>t.term===CAR.term&&t.g).length,troB:CAR.tro.filter(t=>t.term===CAR.term&&!t.g).length},choiceStats(N));}

// 대선: 지지율 35 미만은 출마 불가, 35~65는 1~100% 확률, 65 이상은 확실히 당선
const winPct=a=>a<35?0:a>=65?100:Math.round(1+(a-35)*99/30);
function termEnd(){window.scrollTo(0,0);
  const te=evalTerm('done');CAR.terms.push(te);CAR.tEval=CAR.term;MEM.ends[te.eid]=1;msave();
  if(CP.rule==='reign')return reignEnd(te);
  // 개헌(amendPerm)이나 영구집권(dict)이면 임기 한도가 두 배로 늘어난다
  const av=Math.round(cl(S.a)),pct=winPct(av),amended=!!CAR.amendPerm||CAR.amendOK===CAR.term,limit=CP.rule==='single'?!amended:CP.rule==='two'?(CAR.term>=2&&!amended):false;
  const capT=amended||CAR.dict?MAXT*2:MAXT,isLast=CAR.term>=capT||limit,can=!CAR.dict&&pct>0&&!isLast,n=CAR.term+1;
  const risk=av>=35?0:av<15?100:Math.round((35-av)*5);
  // 마지막 승부: 헌법이 막고 있어도 임기 말에 한 번, 개헌을 밀어붙일 수 있다(커리어에 한 번, 지지율 35 이상)
  const lsOK=limit&&!CAR.lastShot&&CAR.amendFail!==CAR.term&&CAR.term<MAXT&&av>=35,lsP=Math.max(.1,Math.min(.8,.15+(av-35)/90+(vVal('P')-40)/160+.05*cnPow('S')));
  te.winP=isLast?'':CAR.dict?100-risk:pct;
  const acol=av>=65?'#2e7d55':av>=35?'#9a6400':'#b3261e';
  const opt=(id,t,sub,col)=>'<button id="'+id+'" style="width:100%;text-align:left;padding:14px 15px;margin-bottom:8px;'+(col?'border-color:'+col+'99;':'')+'"><span style="display:block;font-size:15px;font-weight:600">'+t+'</span><span style="display:block;font-size:12px;color:var(--text-muted);margin-top:3px">'+sub+'</span></button>';
  let msg,btns;
  // 영구집권: 선거 없이 다음 임기로. 지지율이 35 아래면 봉기 위험, 15 아래면 봉기.
  if(CAR.dict){
    if(isLast){msg='<b>'+ageNow()+'세.</b> 종신 집권도 세월은 이기지 못한다. 권좌를 내려놓을 때다.';btns=opt('fin','권좌에서 내려온다','종신 집권을 마친다','#2f5f99');}
    else if(risk>=100){msg='민심이 완전히 등을 돌렸다. <b>광장에 백만 명이 모였고, 군도 흔들린다.</b>';btns=opt('dep','운명을 맞는다','민중 봉기가 일어난다','#b3261e');}
    else{msg='<b>선거는 없다.</b> 비상통치기구가 당신의 집권을 '+n+'기로 연장한다.'+(risk?' 다만 민심이 흔들린다. <b>봉기 가능성 '+risk+'%</b>.':'');
      btns=opt('stay',n+'기 집권을 이어 간다',(risk?'봉기 위험 '+risk+'% · ':'투표 없이 다음 임기로 · ')+'다음 임기에는 새로운 위기가 온다','#b3261e')+
        opt('retire','스스로 권좌에서 내려온다','여기서 커리어를 마친다','#2f5f99');}}
  else if(can){msg=pct>=100?'압도적인 지지. <b>출마하면 반드시 당선된다.</b>':'출마할 수 있다. <b>당선 가능성 '+pct+'%</b> · 떨어지면 그대로 커리어가 끝난다.';
    btns=(amended?opt('run','고친 헌법으로 '+n+'선에 도전한다','당선 가능성 '+pct+'% · '+(CAR.amendHow||'개헌')+'으로 열린 길이다','#b3261e'):
      opt('run','재선에 도전한다','당선 가능성 '+pct+'% · 다음 임기에는 전혀 다른 위기가 온다','#2f4a6b'))+
      opt('retire',amended?'개헌은 했지만 물러난다':'명예롭게 퇴임한다','여기서 커리어를 마친다','#2f5f99');}
  else{msg=limit?(CP.rule==='single'?'<b>'+YRS+'년 단임.</b> 헌법이 연임을 허락하지 않는다. 임기를 마치고 물러난다.':'<b>수정헌법 22조.</b> 세 번째 임기는 없다. 임기를 마치고 물러난다.'):isLast?(amended?'<b>'+ageNow()+'세.</b> 고친 헌법도 세월은 막지 못한다. 더는 출마할 기력이 없다.':'더는 출마할 수 없다. <b>시대가 바뀌었다.</b>'):'지지율이 35에 미치지 못했다. <b>출마조차 할 수 없다.</b> 정권이 교체된다.';
    btns=(lsOK?opt('last','마지막 승부: 임기 말 개헌을 밀어붙인다','성공 가능성 '+Math.round(lsP*100)+'% · 통과하면 출마하지만 권력이 쏠리고 견제·민심이 크게 깎인다 · 실패하면 쫓겨난다 · 커리어에 한 번','#b3261e'):'')+
      opt('fin',limit?'임기를 마치고 퇴임한다':'커리어 결산 보기','지금까지의 인생을 돌아본다');}
  const mk=(v,t,c)=>'<span style="position:absolute;left:calc('+v+'% - 1px);top:-5px;bottom:-5px;width:2px;background:'+c+'"></span>';
  R.innerHTML='<div style="animation:fdIn .4s ease-out">'+
   lab(CAR.term+'기 정부 · 임기 만료 · '+ageNow()+'세')+tip('elect')+
   '<div class="cd sealhit" style="position:relative;background:var(--surface-2);border:1px solid var(--border);border-radius:12px;padding:16px;margin-bottom:12px;overflow:hidden">'+
   '<div class="seal" style="--sc:'+GCOL[te.g]+'"><b>'+te.g+'</b><span>임기 평가</span></div>'+
   '<div style="font-size:11px;color:var(--text-muted);margin-bottom:6px">이번 임기의 평가 · '+te.scenario+'</div>'+
   '<div style="font-size:22px;font-weight:600;color:'+te.col+';line-height:1.3;margin-bottom:8px;padding-right:80px">'+te.ti+'</div>'+
   '<div style="font-size:14px;color:var(--text-secondary);line-height:1.75">'+words(te.ds,200)+'</div></div>'+
   card(lab('임기 말 지지율')+
     '<div style="position:relative;height:16px;border-radius:8px;background:linear-gradient(90deg,rgba(179,38,30,.10) 0 35%,rgba(154,100,0,.12) 35% 65%,rgba(46,125,85,.12) 65% 100%);margin:4px 0 8px"><span style="position:absolute;left:0;top:0;bottom:0;width:'+av+'%;border-radius:8px;background:'+acol+';animation:barG 1.3s cubic-bezier(.2,.8,.2,1) both"></span>'+
     mk(35,'출마','rgba(29,27,24,.55)')+mk(65,'확정','rgba(29,27,24,.55)')+'</div>'+
     '<div style="position:relative;height:14px;font-size:11px;color:var(--text-muted)"><span style="position:absolute;left:0">0</span><span style="position:absolute;left:35%;transform:translateX(-50%);color:var(--text-secondary);font-weight:600">35 출마</span><span style="position:absolute;left:65%;transform:translateX(-50%)">65 당선 확정</span><span style="position:absolute;right:0">100</span></div>'+
     (can&&pct<100?'<div style="margin-top:12px;display:flex;align-items:center;gap:10px"><span style="font-size:12px;color:var(--text-secondary);flex-shrink:0">당선 가능성</span><span style="position:relative;flex:1;height:8px;border-radius:4px;background:rgba(29,27,24,.07);overflow:hidden"><span style="position:absolute;left:0;top:0;bottom:0;width:'+pct+'%;background:#2f4a6b;border-radius:4px;animation:barG 1.1s cubic-bezier(.2,.8,.2,1) both;animation-delay:.3s"></span></span><b style="font-size:15px">'+pct+'%</b></div>':'')+
     '<div style="font-size:14px;margin-top:10px;line-height:1.7">'+msg+'</div>')+
   btns+'</div>';
  SFX.stamp(.78);SFX.grade(te.g,.78);bindTips();termCine(te);
  const b=id=>document.getElementById(id);
  if(b('run'))b('run').onclick=()=>{SFX.click();te.decision=amended?'개헌 후 '+n+'선 도전':'재선 도전';logSpecial(te.decision,amended?25:0,amended?'권력 집중':'중립');election(amended,pct,te);};
  if(b('retire'))b('retire').onclick=()=>{SFX.click();te.decision='퇴임 (출마 가능했음)';CAR.retireElig=true;logSpecial('퇴임 (출마 가능했음)',-10,'견제·분산');careerEnd('retire');};
  if(b('last'))b('last').onclick=()=>{SFX.click();lastShot(te,lsP,n);};
  if(b('stay'))b('stay').onclick=()=>{SFX.click();te.decision='무투표 집권 연장';logSpecial(te.decision,30,'권력 집중');
    if(Math.random()*100>=risk){te.elect=risk?'봉기 진압':'무투표';CAR.elections.push(n+'기 '+te.elect);
      if(!risk)return newTerm();
      S.a=cl(S.a-3);S.chk=cl(S.chk-4);
      return breaking({k:'bad',h:'전국 동시 집회, 계엄군 투입으로 해산',s:'비상통치기구 "질서 회복"… 사상자 집계는 발표되지 않아',b:'광장은 비워졌다. '+n+'기 집권이 시작됐지만, 그날의 사진은 지워지지 않는다.'},()=>newTerm());}
    te.elect='봉기';CAR.elections.push(n+'기 봉기');
    breaking({k:'bad',h:'민중 봉기… 군, 시위대에 발포 거부',s:'비상통치기구 붕괴, 대통령 행방 묘연',b:'총을 든 사람들이 끝내 등을 돌렸다. 영구집권은 '+CAR.term+'기에서 끝났다.'},()=>careerEnd('ousted'));};
  if(b('dep'))b('dep').onclick=()=>{SFX.click();te.decision='민중 봉기';careerEnd('ousted');};
  if(b('fin'))b('fin').onclick=()=>{SFX.click();te.decision=CAR.dict?'종신 집권 끝에 퇴장':limit?'임기 완료 (연임 불가)':isLast?'임기 한도로 퇴장':'출마 불가 (지지율 35 미만)';careerEnd(CAR.dict?'lifelong':limit?'served':isLast?'limit':'lost');};}
function lastShot(te,p,n){CAR.lastShot=1;const ok=Math.random()<p,us=CP.id==='usa';RUN.lastShot=(ok?'성공':'실패')+' ('+Math.round(p*100)+'%)';
  logSpecial('임기 말 개헌 강행 · '+(ok?'통과':'부결'),30,'권력 집중');
  if(!ok){SFX.voteFail();te.decision='임기 말 개헌 강행 → 부결';
    return breaking({k:'bad',h:us?'수정헌법 22조 폐지안 부결… "3선 야욕" 역풍':'임기 말 개헌안 부결… 대통령 퇴진 요구 확산',s:'마지막 승부가 무너졌다. 여당마저 등을 돌렸다.',b:'광장은 "헌법을 지켜라"는 구호로 가득 찼다. 임기는 불명예 속에 끝났다.'},()=>careerEnd('amendfail'));}
  SFX.votePass();spAmend(us?'임기 말 22조 폐지':'임기 말 개헌');te.decision='임기 말 개헌 강행 → 통과';
  S.p=cl(S.p+8);S.chk=cl(S.chk-10);S.u=cl(S.u+10);S.c=cl(S.c+5);S.a=cl(S.a-6);
  CAR.tro.push({id:'lastshot',n:'임기 말 개헌 강행',g:0,term:CAR.term,year:YRS});
  breaking({k:'bad',h:us?'수정헌법 22조 폐지안 가까스로 통과':'임기 말 개헌안 가까스로 통과… 연임의 길 열려',s:'통과는 됐다. 정권의 정당성에는 깊은 상처가 남았다.',b:'야권은 "헌정 질서에 대한 도전"이라며 장외 투쟁을 선언했다. 견제 장치는 눈에 띄게 약해졌다.'},()=>{
    const av=Math.round(cl(S.a)),pct=winPct(av);window.scrollTo(0,0);
    R.innerHTML='<div style="animation:fdIn .35s ease-out">'+lab(CAR.term+'기 정부 · 개헌 직후')+card('<div class="hd" style="font-size:22px;margin-bottom:8px">고친 헌법, 남은 질문</div>'+
      '<div style="font-size:14px;line-height:1.75;color:var(--text-secondary)">개헌은 통과했다. 대가로 권력은 커지고 견제와 민심은 깎였다. 지금 지지율은 <b>'+av+'</b>, '+(pct>0?'당선 가능성은 <b>'+pct+'%</b>다.':'<b>출마선 35에 미치지 못한다.</b>')+'</div>')+
      (pct>0?'<button id="lsRun" class="pri" style="width:100%;padding:15px;font-size:15px;margin-bottom:8px">고친 헌법으로 '+n+'선에 도전한다</button>':'')+
      '<button id="lsOut" style="width:100%;padding:13px;font-size:14px">'+(pct>0?'개헌만 남기고 물러난다':'커리어 결산 보기')+'</button></div>';
    const r=document.getElementById('lsRun');if(r)r.onclick=()=>{SFX.click();te.decision='임기 말 개헌 후 '+n+'선 도전';election(true,pct,te);};
    document.getElementById('lsOut').onclick=()=>{SFX.click();te.decision+=pct>0?' 후 퇴임':' 후 출마 불가';careerEnd(pct>0?'retire':'lost');};});}
// 조선: 치세가 끝날 때마다 민심의 심판. 35 미만이면 반정 위험, 20 미만이면 반정.
function reignEnd(te){const av=Math.round(cl(S.a)),isLast=CAR.term>=MAXT,risk=av>=35?0:av<20?100:Math.round((35-av)*100/15),n=CAR.term+1;
  te.winP=isLast?'':100-risk;
  const acol=av>=65?'#2e7d55':av>=35?'#9a6400':'#b3261e';
  const opt=(id,t,sub,col)=>'<button id="'+id+'" style="width:100%;text-align:left;padding:14px 15px;margin-bottom:8px;'+(col?'border-color:'+col+'99;':'')+'"><span style="display:block;font-size:15px;font-weight:600">'+t+'</span><span style="display:block;font-size:12px;color:var(--text-muted);margin-top:3px">'+sub+'</span></button>';
  let msg,btns;
  if(isLast){msg='옥좌에 오른 지 '+(CAR.term*YRS)+'년. <b>이제 세자에게 자리를 물려줄 때다.</b>';btns=opt('fin','세자에게 선위한다','치세를 마친다','#2f5f99');}
  else if(risk>=100){msg='민심이 완전히 떠났다. <b>반정의 칼날이 대궐 문 앞에 와 있다.</b>';btns=opt('dep','운명을 맞는다','반정이 일어난다','#b3261e');}
  else{msg=risk?'민심이 흔들린다. 치세를 이어 가면 <b>반정이 일어날 가능성 '+risk+'%</b>.':'민심이 안정돼 있다. <b>치세를 이어 갈 수 있다.</b>';
    btns=opt('run',n+'번째 치세를 이어 간다',risk?'반정 위험 '+risk+'% · 다음 치세에는 새로운 시련이 온다':'다음 치세에는 새로운 시련이 온다','#2f4a6b')+opt('retire','세자에게 선위한다','스스로 물러나 상왕이 된다','#2f5f99');}
  R.innerHTML='<div style="animation:fdIn .4s ease-out">'+lab(CAR.term+'번째 치세 · '+YRS+'년의 끝 · '+ageNow()+'세')+
   '<div class="cd sealhit" style="position:relative;background:var(--surface-2);border:1px solid var(--border);border-radius:12px;padding:16px;margin-bottom:12px;overflow:hidden">'+
   '<div class="seal" style="--sc:'+GCOL[te.g]+'"><b>'+te.g+'</b><span>치세 평가</span></div>'+
   '<div style="font-size:11px;color:var(--text-muted);margin-bottom:6px">이번 치세의 평가 · '+te.scenario+'</div>'+
   '<div style="font-size:22px;font-weight:600;color:'+te.col+';line-height:1.3;margin-bottom:8px;padding-right:80px">'+te.ti+'</div>'+
   '<div style="font-size:14px;color:var(--text-secondary);line-height:1.75">'+words(te.ds,200)+'</div></div>'+
   card(lab('치세 끝의 민심')+'<div style="position:relative;height:16px;border-radius:8px;background:linear-gradient(90deg,rgba(179,38,30,.14) 0 20%,rgba(179,38,30,.08) 20% 35%,rgba(46,125,85,.10) 35% 100%);margin:4px 0 8px"><span style="position:absolute;left:0;top:0;bottom:0;width:'+av+'%;border-radius:8px;background:'+acol+';animation:barG 1.3s cubic-bezier(.2,.8,.2,1) both"></span></div>'+
     '<div style="position:relative;height:14px;font-size:11px;color:var(--text-muted)"><span style="position:absolute;left:20%;transform:translateX(-50%)">20 반정</span><span style="position:absolute;left:35%;transform:translateX(-50%);color:var(--text-secondary);font-weight:600">35 안전</span><span style="position:absolute;right:0">100</span></div>'+
     '<div style="font-size:14px;margin-top:10px;line-height:1.7">'+msg+'</div>')+btns+'</div>';
  SFX.stamp(.78);SFX.grade(te.g,.78);termCine(te);
  const b=id=>document.getElementById(id);
  if(b('run'))b('run').onclick=()=>{SFX.click();te.decision='치세를 이어 감';logSpecial('치세를 이어 감',0,'중립');if(!risk){te.elect='유지';CAR.elections.push(n+'번째 치세 안정');return newTerm();}election(false,100-risk,te);};
  if(b('retire'))b('retire').onclick=()=>{SFX.click();te.decision='선위 (이어 갈 수 있었음)';CAR.retireElig=true;logSpecial('선위 (이어 갈 수 있었음)',-10,'견제·분산');careerEnd('retire');};
  if(b('dep'))b('dep').onclick=()=>{SFX.click();te.decision='반정';careerEnd('deposed');};
  if(b('fin'))b('fin').onclick=()=>{SFX.click();te.decision='치세 완료';careerEnd('served');};}

// 대통령 선거(조선 반정 제외)는 당선이 확정이 아니면 개표 전에 TV 토론이 열린다. 토론 결과로 당선 가능성이 오르내린다.
const DB_D=[14,6,-4,-10];
function debateGate(amend,pct,te){window.scrollTo(0,0);const n=CAR.term+1;
  R.innerHTML='<div style="animation:fdIn .35s ease-out">'+lab((amend?n+'선 대선':n+'번째 대통령 선거')+' · 투표 사흘 전')+
   card('<div class="hd" style="font-size:22px;margin-bottom:8px">대선 TV 토론</div><div style="font-size:14px;line-height:1.75;color:var(--text-secondary)">투표 사흘 전, 생중계 TV 토론이 잡혔다. 도전자가 이번 임기의 약점을 파고든다. 잘 받아치면 판이 뒤집히고, 무너지면 앞서던 표도 흔들린다. 지금 당선 가능성은 <b>'+pct+'%</b>다.</div>'+
     '<div style="font-size:12.5px;color:var(--text-muted);margin-top:8px">압승 +'+DB_D[0]+'%p · 우세 +'+DB_D[1]+'%p · 열세 '+DB_D[2]+'%p · 완패 '+DB_D[3]+'%p</div>')+
   '<button id="dbIn" class="pri" style="width:100%;padding:15px;font-size:15px;margin-bottom:8px">토론에 나간다</button>'+
   '<button id="dbNo" style="width:100%;padding:13px;font-size:14px">토론을 거부한다 <span style="font-size:12px;color:var(--text-muted)">· "토론 회피" 비판으로 당선 가능성 −3%p</span></button></div>';
  const go=(p2,why)=>{te.debate=why;RUN.debate=why;election(amend,p2,te,1);};
  document.getElementById('dbNo').onclick=()=>{SFX.click();te.dbD=-3;go(Math.max(1,pct-3),'거부');};
  document.getElementById('dbIn').onclick=()=>{SFX.click();window.scrollTo(0,0);R.innerHTML='<div style="animation:fdIn .35s ease-out">'+lab('대선 TV 토론 · 생중계')+'<div id="dbBox"></div></div>';
    debateRun(document.getElementById('dbBox'),{pct:pct,amend:amend},(t,v)=>{te.dbD=DB_D[t];go(Math.max(1,Math.min(99,pct+DB_D[t])),['압승','우세','열세','완패'][t]+' '+v+'%');});};}
function election(amend,pct,te,deb){
  if(!deb&&CP.rule!=='reign'&&pct>0&&pct<100)return debateGate(amend,pct,te);
  window.scrollTo(0,0);
  const n=CAR.term+1,win=Math.random()*100<pct,jit=Math.random()*4-2;
  const share=win?Math.max(50.4,Math.min(79,50.5+(S.a-50)*.55+jit)):Math.min(49.6,Math.max(28,48+(S.a-50)*.45+jit));
  const RG=CP.rule==='reign';te.elect=RG?(win?'반정 진압':'반정'):win?'당선':'낙선';te.winP=pct;CAR.elections.push(n+(RG?'번째 치세 ':'기 ')+pct+'% '+te.elect);
  R.innerHTML='<div style="animation:fdIn .35s ease-out;padding-top:10px">'+
   lab(RG?'반정 모의 · '+n+'번째 치세의 문턱':amend?n+'선 대선 · 고친 헌법 아래':(n)+'번째 대통령 선거')+
   '<div id="vt" style="font-size:24px;font-weight:600;margin-bottom:6px">'+(RG?'궐 밖이 술렁인다':'개표 중')+'</div>'+
   '<div style="font-size:13px;color:var(--text-secondary);margin-bottom:18px">'+(RG?'반정을 꾀하는 무리가 있다는 밀고가 들어왔다. 군사와 대신들은 누구 편에 설 것인가.':amend?'헌법이 바뀌었다. 이제 남은 것은 표다.':'국민이 다시 묻는다. 한 번 더 맡길 것인가.')+' <span style="color:var(--text-muted)">· '+(RG?'진압 가능성 ':'당선 가능성 ')+pct+'%'+(te.dbD!=null&&!RG?' (TV 토론 '+(te.dbD>=0?'+':'')+te.dbD+'%p)':'')+'</span></div>'+
   card('<div style="display:flex;justify-content:space-between;font-size:12px;color:var(--text-muted);margin-bottom:6px"><span>'+(RG?'임금 편에 선 군사':'득표율')+'</span><span id="vp">0%</span></div>'+
     '<div style="position:relative;height:20px;border-radius:10px;background:rgba(29,27,24,.07);overflow:hidden"><span id="vb" style="position:absolute;left:0;top:0;bottom:0;width:0;background:#2f4a6b;border-radius:10px;transition:width 1.6s cubic-bezier(.2,.8,.2,1)"></span>'+
     '<span style="position:absolute;left:calc(50% - 1px);top:0;bottom:0;width:2px;background:#fff;opacity:.8"></span></div>')+
   '<div id="won" style="text-align:center;margin:22px 0;min-height:70px"></div>'+
   '<button id="go2" class="pri" style="width:100%;padding:15px;font-size:15px;opacity:0;pointer-events:none">'+(win?(RG?n+'번째 치세 시작':n+'기 정부 출범'):'커리어 결산 보기')+'</button></div>';
  requestAnimationFrame(()=>requestAnimationFrame(()=>{const vb=document.getElementById('vb');if(vb)vb.style.width=share+'%';}));
  const t0=performance.now();(function f(){const k=Math.min(1,(performance.now()-t0)/1600),el=document.getElementById('vp');if(!el)return;el.textContent=(share*(1-Math.pow(1-k,3))).toFixed(1)+'%';if(k<1)requestAnimationFrame(f);})();
  SFX.roll(1.7);
  setTimeout(()=>{const w=document.getElementById('won');if(!w)return;document.getElementById('vt').textContent=RG?(win?'반정 모의를 진압했다':'반정이 일어났다'):'개표 완료';
    if(win){SFX.stamp(.3);SFX.win(.3);w.innerHTML='<div style="display:inline-block;font-size:40px;font-weight:800;color:#2e7d55;letter-spacing:6px;border:3px solid #2e7d55;border-radius:10px;padding:4px 18px;animation:stamp .6s cubic-bezier(.2,1.4,.4,1) both">'+(RG?'진압':'당선')+'</div>';}
    else{SFX.stamp(.3);SFX.lose(.3);vib([90,60,120]);w.innerHTML='<div style="display:inline-block;font-size:40px;font-weight:800;color:#b3261e;letter-spacing:6px;border:3px solid #b3261e;border-radius:10px;padding:4px 18px;animation:stamp .6s cubic-bezier(.2,1.4,.4,1) both">'+(RG?'폐위':'낙선')+'</div><div style="font-size:13px;color:var(--text-secondary);margin-top:12px">'+pct+'%의 가능성은 이번에 오지 않았다.</div>';}
    const g=document.getElementById('go2');g.style.opacity=1;g.style.pointerEvents='auto';g.style.transition='opacity .3s';
    g.onclick=()=>{if(win){SFX.start();newTerm();}else{SFX.click();careerEnd(RG?'deposed':'defeated');}};},1800);}

/* ---------- 커리어 결산 ---------- */
const EXH={served:'임기를 마치고 물러났다',deposed:'반정으로 폐위됐다',retire:'명예롭게 퇴임했다',lost:'지지율 미달로 출마하지 못했다',defeated:'선거에서 패배했다',limit:'더는 출마할 수 없었다',ousted:'거리로 쫓겨났다',amendfail:'무리한 개헌이 무너지며 쫓겨났다',coupfail:'내란이 실패하며 체포됐다',lifelong:'종신 집권 끝에 권좌에서 내려왔다',medfail:'의료 붕괴로 정권이 무너졌다',ecofail:'경제 붕괴로 정권이 무너졌다',quit:'스스로 하야했다'};
function careerStats(){const N=LOG.filter(x=>x.eventType!=='임기 결정'),avg=a=>a.length?a.reduce((p,q)=>p+q,0)/a.length:0;
  const cs=CAR.cs.length?CAR.cs:[S.c],ts=CAR.ts.length?CAR.ts:[S.trn],us=CAR.us.length?CAR.us:[S.u],ss=CAR.ss.length?CAR.ss:[S.saf];
  const pc={};N.forEach(x=>{if(x.priority&&x.priority!=='없음')pc[x.priority]=(pc[x.priority]||0)+1;});
  const prio=Object.keys(pc).sort((a,b)=>pc[b]-pc[a])[0]||'';
  const h=Math.floor(N.length/2),h1=N.length>=8?avg(N.slice(0,h).map(x=>x.dirScore)):0,h2=N.length>=8?avg(N.slice(h).map(x=>x.dirScore)):0;
  return {dir:avg(N.map(x=>x.dirScore)),perf:avg(CAR.terms.map(t=>t.sc)),cor:avg(cs),trn:avg(ts),u:avg(us),saf:avg(ss),ins:avg(CAR.terms.map(t=>t.ins||0)),
    prio:prio,h1:h1,h2:h2,terms:CAR.term,exit:CAR.exit,amend:CAR.amend,dict:CAR.dict};}
// 닮은 지도자: 퇴장 방식이 가장 크게 갈라 놓고, 그 위에 통치 방향·성과·지표 습관·업적과 불명예·겪은 사건을 점수로 더한다.
// 가장 잘 맞는 사람을 고르되, 3점 안쪽으로 비슷한 사람이 여럿이면 운이 고르고, 아직 만나지 못한 사람을 조금 앞세운다.
let LEADF=null;
function leadF(C){const s=S||{},tro=CAR.tro||[],T=new Set(tro.map(t=>t.id)),good=tro.filter(t=>t.g).length,sc=(CAR.scen||[]).concat(CP&&CP.scen0?[CP.scen0]:[]);
  const yrs=Math.max(1,(CAR.term-1)*YRS+Math.ceil((s.turn||0)/PY));
  return {ex:C.exit||'served',d:C.dir||0,f:C.perf||0,n:C.terms||1,am:C.amend||0,dict:!!C.dict,cor:C.cor,trn:C.trn,u:C.u,saf:C.saf,ins:C.ins||0,pr:C.prio||'',
   turn:C.h1>=2&&C.h2<=-3?-1:C.h1<=-2&&C.h2>=3?1:0,   // 노선을 뒤집었는가: -1 집중→분산, 1 분산→집중
   T:T,gy:good/yrs,by:(tro.length-good)/yrs,bw:CAR.boldWin||0,bl:CAR.boldLoss||0,crush:CAR.crush||0,
   mil:s.mil==null?50:s.mil,e:s.e==null?50:s.e,a:s.a==null?50:s.a,m:s.m==null?50:s.m,
   war:sc.some(k=>/^(war|war2|wae)$/.test(k)),fin:sc.some(k=>/^(fin|recess)$/.test(k)),oil:sc.indexOf('oil')>=0,
   mart:T.has('martial')||T.has('selfcoup'),coup:T.has('coup')||T.has('selfcoup'),end:!!CAR.endemic,camp:CAR.camp,
   adv:(CAR.cn||[]).filter(i=>i!=null).length,winLow:(CAR.terms||[]).some(t=>t.elect==='당선'&&t.winP<50),sp:(CAR.spEnds||[]).join(' ')};}
// lup(x,a,b): x가 a일 때 0, b일 때 1(그 사이는 고르게, 밖은 0과 1로 자른다). a>b면 x가 작을수록 커진다.
const lup=(x,a,b)=>Math.max(0,Math.min(1,(x-a)/(b-a)));
// 권력을 늘린 적이 없어야 어울리는 사람들: 개헌이나 계엄이 있으면 크게 깎는다
